<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { detalleRequerimiento,finalizarRequerimiento,liberarRequerimiento,listarRequerimientos,recibirRequerimiento,registrarRequerimiento } from '../services/requerimientos'
import type { Options, Requerimiento } from '../interfaces/requerimientos.interface'
const rows=ref<Requerimiento[]>([]),options=ref<Options>({estados:[],origenes:[],categorias:[],usuarios:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),createModal=ref(false),finishModal=ref(false),detail=ref<Requerimiento|null>(null),attachment=ref<File|null>(null),solutionFile=ref<File|null>(null)
const filters=reactive({criterio:'',estado:'',periodo:new Date().toISOString().slice(0,7),bandeja:'todos',page:1}),form=reactive({observacion:'',origen:'WEB',fecha_iniciado:'',user_id:''}),finish=reactive({categoria_id:'',solucion:'',fecha_atencion:'',usuarios_atendidos:[] as number[],usuarios_colaboran:[] as number[]})
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarRequerimientos(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;options.value=r.options}catch(e){error.value=message(e)}finally{loading.value=false}}
function openCreate(){Object.assign(form,{observacion:'',origen:'WEB',fecha_iniciado:'',user_id:''});attachment.value=null;createModal.value=true}async function save(){if(form.observacion.trim().length<10){error.value='El detalle debe tener al menos 10 caracteres.';return}const data=new FormData();Object.entries(form).forEach(([k,v])=>{if(v)data.append(k,v)});if(attachment.value)data.append('archivo',attachment.value);saving.value=true;error.value='';try{await registrarRequerimiento(data);createModal.value=false;success.value='Requerimiento reportado correctamente.';await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function show(item:Requerimiento){try{detail.value=await detalleRequerimiento(item.id)}catch(e){error.value=message(e)}}async function action(item:Requerimiento,type:'recibir'|'liberar'){if(!confirm(`¿Confirmar ${type} el requerimiento #${item.id}?`))return;try{type==='recibir'?await recibirRequerimiento(item.id):await liberarRequerimiento(item.id);success.value='Estado actualizado correctamente.';detail.value=null;await load()}catch(e){error.value=message(e)}}
function openFinish(item:Requerimiento){detail.value=item;Object.assign(finish,{categoria_id:'',solucion:'',fecha_atencion:'',usuarios_atendidos:[],usuarios_colaboran:[]});solutionFile.value=null;finishModal.value=true}async function saveFinish(){if(!detail.value||!finish.categoria_id||finish.solucion.trim().length<15){error.value='Seleccione la categoría y describa la solución con al menos 15 caracteres.';return}const data=new FormData();data.append('categoria_id',String(finish.categoria_id));data.append('solucion',finish.solucion);if(finish.fecha_atencion)data.append('fecha_atencion',finish.fecha_atencion);finish.usuarios_atendidos.forEach(x=>data.append('usuarios_atendidos[]',String(x)));finish.usuarios_colaboran.forEach(x=>data.append('usuarios_colaboran[]',String(x)));if(solutionFile.value)data.append('archivo',solutionFile.value);saving.value=true;try{await finalizarRequerimiento(detail.value.id,data);finishModal.value=false;detail.value=null;success.value='Solución registrada y requerimiento finalizado.';await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
function pick(e:Event,target:'request'|'solution'){const value=(e.target as HTMLInputElement).files?.[0]||null;if(target==='request')attachment.value=value;else solutionFile.value=value}function statusClass(v:string){return v.replaceAll(' ','-')}function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / HelpDesk / Requerimientos</nav><header class="hero"><div class="mark">HD</div><div><small>SOPORTE INTERNO</small><h1>Requerimientos de asistencia</h1><p>Registro, asignación y seguimiento de incidencias técnicas y funcionales.</p></div><strong>{{total}} tickets</strong><button @click="openCreate">+ Reportar requerimiento</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><div class="tabs"><button v-for="x in [{id:'todos',name:'Todos'},{id:'disponibles',name:'Sin recibir'},{id:'pendientes',name:'Mis pendientes'},{id:'finalizados',name:'Finalizados'}]" :key="x.id" :class="{active:filters.bandeja===x.id}" @click="filters.bandeja=x.id;load(1)">{{x.name}}</button></div><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Código o descripción" @keyup.enter="load(1)"></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option v-for="x in options.estados" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Periodo<input v-model="filters.periodo" type="month"></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando requerimientos…</div><div v-else-if="!rows.length" class="empty">No se encontraron requerimientos.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id"><header><div><small>TICKET</small><b>#{{String(item.id).padStart(6,'0')}}</b></div><em :class="statusClass(item.estado)">{{item.estado}}</em></header><p>{{item.observacion}}</p><dl><div><dt>Solicitante</dt><dd>{{item.solicitante||'—'}}</dd></div><div><dt>Oficina</dt><dd>{{item.oficina||'—'}}</dd></div><div><dt>Registro</dt><dd>{{item.fecha_iniciado}}</dd></div><div><dt>Responsable</dt><dd>{{item.responsable||'Sin asignar'}}</dd></div></dl><footer><button @click="show(item)">Ver detalle</button><button v-if="item.puede_recibir" class="good" @click="action(item,'recibir')">Recibir</button><button v-if="item.puede_liberar" @click="action(item,'liberar')">Liberar</button><button v-if="item.puede_finalizar" class="good" @click="openFinish(item)">Finalizar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="createModal" class="backdrop" @mousedown.self="createModal=false"><form class="modal" @submit.prevent="save"><header><div><small>NUEVA ASISTENCIA</small><h2>Reportar requerimiento</h2></div><button type="button" @click="createModal=false">×</button></header><p class="hint">Explique el inconveniente con el sistema, equipo informático o asistencia funcional requerida.</p><div class="grid"><label>Medio<select v-model="form.origen"><option v-for="x in options.origenes" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Fecha de registro<input v-model="form.fecha_iniciado" type="datetime-local"><small>Solo necesaria para registros retrospectivos.</small></label></div><label>Detalle del requerimiento *<textarea v-model.trim="form.observacion" rows="6" minlength="10"></textarea></label><label>Archivo adjunto<input type="file" @change="pick($event,'request')"><small>Opcional.</small></label><footer><button type="button" class="clear" @click="createModal=false">Cancelar</button><button :disabled="saving">{{saving?'Reportando…':'Reportar'}}</button></footer></form></div>
<div v-if="detail&&!finishModal" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>DETALLE DE ASISTENCIA</small><h2>Ticket #{{String(detail.id).padStart(6,'0')}}</h2><p>{{detail.estado}} · {{detail.fecha_iniciado}}</p></div><button @click="detail=null">×</button></header><p class="description">{{detail.observacion}}</p><div class="summary"><div><b>{{detail.solicitante||'—'}}</b><span>Solicitante</span></div><div><b>{{detail.responsable||'Sin asignar'}}</b><span>Responsable</span></div><div><b>{{detail.categoria||'—'}}</b><span>Categoría</span></div></div><template v-if="detail.solucion"><h3>Solución aplicada</h3><p class="solution">{{detail.solucion}}</p></template><h3>Historial</h3><div class="list"><div v-for="x in detail.movimientos" :key="x.id"><b>{{x.estado}}</b><span>{{x.usuario}} · {{x.fecha}}</span></div></div><h3>Participantes</h3><div class="list"><div v-for="x in detail.participantes" :key="x.id"><b>{{x.nombre}}</b><span>{{x.rol}} · {{x.oficina}}</span></div></div><footer><button class="clear" @click="detail=null">Cerrar</button><button v-if="detail.puede_recibir" @click="action(detail,'recibir')">Recibir</button><button v-if="detail.puede_finalizar" @click="openFinish(detail)">Registrar solución</button></footer></section></div>
<div v-if="finishModal&&detail" class="backdrop" @mousedown.self="finishModal=false"><form class="modal" @submit.prevent="saveFinish"><header><div><small>CIERRE DE TICKET #{{detail.id}}</small><h2>Registrar solución</h2></div><button type="button" @click="finishModal=false">×</button></header><div class="grid"><label>Categoría *<select v-model="finish.categoria_id"><option value="">Seleccione</option><option v-for="x in options.categorias" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Fecha de atención<input v-model="finish.fecha_atencion" type="datetime-local"></label></div><label>Solución aplicada *<textarea v-model.trim="finish.solucion" rows="6" minlength="15"></textarea></label><label>Evidencia de solución<input type="file" @change="pick($event,'solution')"><small>Opcional.</small></label><footer><button type="button" class="clear" @click="finishModal=false">Cancelar</button><button :disabled="saving">{{saving?'Finalizando…':'Finalizar requerimiento'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#db4b4b;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.56rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.63rem}.flash.error{color:#a13f43;background:#fff0f0}.tabs{margin-top:13px;display:flex;gap:4px}.tabs button{padding:10px 16px;border:0;border-radius:7px 7px 0 0;color:#718087;background:#e7ebed;font-size:.56rem}.tabs button.active{color:#fff;background:var(--accent)}.filters{padding:12px;display:flex;align-items:end;gap:8px;border-radius:0 9px 9px 9px;background:#fff}.filters label{flex:1;font-size:.53rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.6rem}.cards{margin-top:13px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{display:flex;flex-direction:column;padding:14px;border-top:3px solid var(--accent);border-radius:9px;background:#fff}.cards article>header{display:flex;justify-content:space-between}.cards header b,.cards header small{display:block}.cards em{padding:4px 7px;border-radius:10px;background:#edf1f3;font-size:.48rem;font-style:normal}.cards em.sin-recibir,.cards em.liberado{color:#a36a18;background:#fff6e8}.cards em.recibido{color:#27668a;background:#edf6fb}.cards em.finalizado{color:#287153;background:#eff9f4}.cards article>p{min-height:50px;color:#66757c;font-size:.56rem}.cards dl{display:grid;grid-template-columns:1fr 1fr;gap:7px}.cards dt{color:#8a969c;font-size:.46rem}.cards dd{margin:2px 0;font-size:.52rem;font-weight:700}.cards footer{margin-top:auto;display:flex;justify-content:flex-end}.cards footer button{border:0;color:var(--accent);background:none;font-size:.5rem;font-weight:700}.cards footer .good{color:#287153}.empty{margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,760px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.modal label small{display:block;margin-top:4px;color:#89959b}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.hint,.description,.solution{padding:11px;border-left:3px solid var(--accent);background:#f6f8f9;font-size:.59rem}.solution{border-color:#287153}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.summary{margin:14px 0;display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.summary div{padding:11px;text-align:center;border-radius:7px;background:#f0f3f5}.summary b,.summary span{display:block;font-size:.55rem}.modal h3{font-size:.65rem}.list div{padding:8px;display:flex;justify-content:space-between;border-bottom:1px solid #e8ecee;font-size:.55rem}.list span{color:#7d898f}.detail{width:min(100%,850px)}@media(max-width:900px){.cards{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:560px){.cards,.grid,.summary{grid-template-columns:1fr}.tabs{overflow:auto}}
</style>
